        },
        "o": {
          "type": "literal",
          "value": "Value-reference targets must register only under shared-scope parents accepted by the target gate: file, class, module, struct, or enum. Evidence: docs/design/value-reference-edges-playbook.md#2 §5A says the target gate now accepts `file:`, `class:`, `module:`, `struct:`, and `enum:` parents, and warns that a missing parent kind makes a language silently emit no value-reference edges even when constant nodes exist.",
          "datatype": "http://www.w3.org/2001/XMLSchema#string"
